/* Kodeområdet i linje-id-en → Enturs logo. */
export const LOGO_FOR = {
  RUT: { ikon: 'RuterNoTextIcon', navn: 'Ruter' },
  VYG: { ikon: 'VyIcon', navn: 'Vy' },
  VYB: { ikon: 'VyIcon', navn: 'Vy' },
  VYX: { ikon: 'VyIcon', navn: 'Vy' },
  NBU: { ikon: 'VyIcon', navn: 'Vy' },
  SKY: { ikon: 'SkyssNoTextIcon', navn: 'Skyss' },
  ATB: { ikon: 'AtBIcon', navn: 'AtB' },
  KOL: { ikon: 'KolumbusIcon', navn: 'Kolumbus' },
  BRA: { ikon: 'BrakarNoTextIcon', navn: 'Brakar' },
  AKT: { ikon: 'AKTIcon', navn: 'AKT' },
  SJN: { ikon: 'SJNordIcon', navn: 'SJ' },
  GOA: { ikon: 'GOAIcon', navn: 'Go-Ahead' },
  INN: { ikon: 'InnlandstrafikkIcon', navn: 'Innlandstrafikk' },
  OST: { ikon: 'OstfoldIcon', navn: 'Østfold kollektiv' },
  VKT: { ikon: 'VKTIcon', navn: 'VKT' },
  TEL: { ikon: 'FarteIcon', navn: 'Farte' },
  MOR: { ikon: 'FramIcon', navn: 'Fram' },
  NOR: { ikon: 'ReisNordlandIcon', navn: 'Reis' },
  TRO: { ikon: 'SvipperIcon', navn: 'Svipper' },
  FIN: { ikon: 'SnelandiaIcon', navn: 'Snelandia' },
};

export function logoFor(linjeId) {
  if (!linjeId || typeof linjeId !== 'string') return null;
  const t = LOGO_FOR[linjeId.split(':')[0]];
  return t ? { ikon: t.ikon, navn: t.navn, ...LOGO[t.ikon] } : null;
}
